# UARD (Untrapped Auto-Repair Diagnostic) ver 1.0.2 - TRUE BASELINE
# Canonical repair endpoint: 3.2.0 / 000-999 audit middleman.
# Hardened for execution-policy, Zone.Identifier, App Control, HTTP 4xx/5xx, partial downloads, and local file failures.
$ErrorActionPreference='Stop'
$UARDName='UARD (Untrapped Auto-Repair Diagnostic)';$UARDVersion='1.0.2';$Root=Split-Path -Parent $MyInvocation.MyCommand.Path;$Middleman='https://untrapped-update-middleman-000-999-production.up.railway.app';$ArtifactBase=$Middleman+'/v1/artifact/';$Report=Join-Path $Root 'repair-success-latest.txt';$BackupRoot=Join-Path $Root 'repair-backups';$log=New-Object 'System.Collections.Generic.List[string]';$changed=$false;$failed=$false;$unknown=$false;$CanonicalCache=@{};$sw=[Diagnostics.Stopwatch]::StartNew();$MaxBytes=8388608
function Log([string]$m){$x='['+(Get-Date -Format HH:mm:ss)+'] '+$m;Write-Host $x;[void]$log.Add($x)}
function HashBytes([byte[]]$b){$s=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($s.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function Normalize([byte[]]$b,[string]$n,[string]$t){if($t -eq 'json'){try{$null=([Text.Encoding]::UTF8.GetString($b).TrimStart([char]0xFEFF)|ConvertFrom-Json -ErrorAction Stop)}catch{throw "invalid canonical JSON for $n"};return $b};$s=[Text.Encoding]::UTF8.GetString($b).TrimStart([char]0xFEFF).Trim();if(-not $s.StartsWith('{')){return $b};try{$j=$s|ConvertFrom-Json -ErrorAction Stop}catch{return $b};$lang='';if($j.PSObject.Properties.Name -contains 'language'){$lang=[string]$j.language}elseif($j.PSObject.Properties.Name -contains 'lang'){$lang=[string]$j.lang};$explicit=$lang.ToLowerInvariant() -in @('powershell','powershell-script','powershellscript','ps1','pwsh');if(-not $explicit){return $b};$enc=str($j.encoding);foreach($k in @('powershell','script','source','code','content','text','body')){if($j.PSObject.Properties.Name -contains $k -and $j.$k -is [string]){$v=[string]$j.$k;if($enc.ToLowerInvariant().Replace('-','') -eq 'base64'){$v=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($v))};return [Text.Encoding]::UTF8.GetBytes($v.TrimEnd()+"`n")}};if($j.PSObject.Properties.Name -contains 'commands' -and $j.commands -is [array] -and @($j.commands|Where-Object{$_ -isnot [string]}).Count -eq 0){return [Text.Encoding]::UTF8.GetBytes((($j.commands -join "`n").TrimEnd()+"`n"))};return $b}
function ReadLimited([IO.Stream]$st){$ms=New-Object IO.MemoryStream;$buf=New-Object byte[] 65536;$total=0;try{while(($r=$st.Read($buf,0,$buf.Length)) -gt 0){$total+=$r;if($total -gt $MaxBytes){throw "canonical artifact exceeds $MaxBytes byte limit"};$ms.Write($buf,0,$r)}}finally{$ms.Dispose()};return $ms.ToArray()}
function RemoteBytes([string]$n,[string]$t){if($CanonicalCache.ContainsKey($n)){return $CanonicalCache[$n]};for($a=1;$a -le 5;$a++){try{Log ('FETCH '+$n+' attempt '+$a+'/5');$q=[Net.HttpWebRequest]::Create($ArtifactBase+$n+'?cb='+[DateTime]::UtcNow.Ticks);$q.Method='GET';$q.Timeout=30000;$q.ReadWriteTimeout=30000;$q.UserAgent='UARD/1.0.2';$q.AllowAutoRedirect=$true;$r=$q.GetResponse();try{if($r.ContentLength -gt $MaxBytes){throw "canonical artifact exceeds $MaxBytes byte limit"};$raw=ReadLimited $r.GetResponseStream();$x=Normalize $raw $n $t}finally{$r.Dispose()};$CanonicalCache[$n]=$x;Log ('DOWNLOAD OK '+$n+' '+$x.Length+' bytes SHA256='+(HashBytes $x));return $x}catch{ $c=0;$detail=$_.Exception.Message;try{$c=[int]$_.Exception.Response.StatusCode}catch{};if($c -eq 409){Log ('HTTP 409 CONFLICT '+$n+': server reported a resource-state conflict; not blindly retrying.');$script:unknown=$true;break};if($c -eq 422){Log ('HTTP 422 UNPROCESSABLE '+$n+': server accepted the request syntax but could not process the content.');$script:failed=$true;break};if($c -eq 404){Log ('HTTP 404 NOT FOUND '+$n+': canonical artifact is absent.');$script:unknown=$true;break};if($c -eq 401 -or $c -eq 403){Log ('HTTP '+$c+' ACCESS DENIED '+$n+': credentials/policy/server access issue; no destructive workaround attempted.');$script:unknown=$true;break};if($c -eq 408 -or $c -eq 425 -or $c -eq 429 -or $c -ge 500 -or $c -eq 0){Log ('TRANSIENT FETCH ERROR '+$n+' HTTP '+$c+'; retrying. '+$detail);if($a -lt 5){Start-Sleep -Seconds ([Math]::Min($a*2,8));continue}}else{Log ('CANONICAL FETCH ERROR '+$n+' HTTP '+$c+': '+$detail)};break}};$script:unknown=$true;Log ('UNVERIFIED '+$n+' canonical source unavailable.');return $null}
function ValidPS([byte[]]$b,[string]$n){if($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage'){Log ('SCRIPT SYNTAX CHECK SKIPPED '+$n+': LanguageMode is '+$ExecutionContext.SessionState.LanguageMode+'; application control may restrict parser APIs.');$script:unknown=$true;return $true};try{$s=[Text.Encoding]::UTF8.GetString($b);$null=[scriptblock]::Create($s);return $true}catch{Log ('SCRIPT VALIDATION FAILED '+$n+': '+$_.Exception.Message);return $false}}
function Backup([string]$p){if(Test-Path -LiteralPath $p){$d=Join-Path $BackupRoot (Get-Date -Format 'yyyyMMdd-HHmmssfff');New-Item -ItemType Directory -Path $d -Force|Out-Null;Copy-Item -LiteralPath $p -Destination (Join-Path $d (Split-Path $p -Leaf)) -Force;Log ('BACKUP '+$p)}}
function Install([string]$p,[byte[]]$b){$d=Split-Path -Parent $p;if(-not(Test-Path -LiteralPath $d)){New-Item -ItemType Directory -Path $d -Force|Out-Null};$tmp=$p+'.uaudtmp-'+[Guid]::NewGuid().ToString('N');try{[IO.File]::WriteAllBytes($tmp,$b);$verify=[IO.File]::ReadAllBytes($tmp);if((HashBytes $verify) -ne (HashBytes $b)){throw 'temporary write verification hash mismatch'};Move-Item -LiteralPath $tmp -Destination $p -Force}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}}
function PolicyDiag{$l=Get-ExecutionPolicy -List|Out-String;Log ('EXECUTION POLICY '+(($l.Trim()-replace '\r?\n',' | ')));$mp=(Get-ExecutionPolicy -Scope MachinePolicy);$up=(Get-ExecutionPolicy -Scope UserPolicy);if($mp -ne 'Undefined' -or $up -ne 'Undefined'){Log 'GROUP POLICY EXECUTION POLICY DETECTED: -ExecutionPolicy Bypass cannot override MachinePolicy/UserPolicy.';$script:unknown=$true};$lm=$ExecutionContext.SessionState.LanguageMode;Log ('LANGUAGE MODE '+$lm);if($lm -ne 'FullLanguage'){Log 'APPLICATION CONTROL / CONSTRAINED LANGUAGE DETECTED; protected script operations may be restricted.';$script:unknown=$true};try{$zone=Get-Item -LiteralPath $PSCommandPath -Stream Zone.Identifier -ErrorAction SilentlyContinue;if($zone){Log 'ZONE.IDENTIFIER PRESENT ON UARD; attempting local unblock.';try{Unblock-File -LiteralPath $PSCommandPath -ErrorAction Stop;Log 'UNBLOCK OK'}catch{Log ('UNBLOCK FAILED: '+$_.Exception.Message);$script:unknown=$true}}else{Log 'ZONE.IDENTIFIER NOT PRESENT'}}catch{Log ('ZONE CHECK UNAVAILABLE: '+$_.Exception.Message);$script:unknown=$true}}
function ToolDiag{$ps=(Get-Command powershell.exe -ErrorAction SilentlyContinue);if($ps){Log ('POWERSHELL '+$ps.Source)}else{Log 'POWERSHELL.EXE NOT FOUND';$script:failed=$true};$cmd=(Get-Command cmd.exe -ErrorAction SilentlyContinue);if(-not $cmd){Log 'CMD.EXE NOT FOUND';$script:unknown=$true}}
Log ($UARDName+' ver '+$UARDVersion+' - TRUE BASELINE');Log ('MIDDLEMAN '+$Middleman);Log 'PROTECTION: no Windows Firewall/WFP/DNS/routes/Hosts/proxy/VPN/adapter/override-policy changes.';PolicyDiag;ToolDiag
$core=@('config.json','packet-filter.ps1','self-repair.ps1','status-untrapped.ps1','ultra-mode.ps1');foreach($n in $core){$p=Join-Path $Root $n;$t=if($n -eq 'config.json'){'json'}else{'ps1'};try{$x=RemoteBytes ('ultra-mode/'+$n) $t}catch{Log ('ARTIFACT EXCEPTION '+$n+': '+$_.Exception.Message);$script:failed=$true;continue};if($null -eq $x){continue};if($t -eq 'ps1' -and -not(ValidPS $x $n)){$script:failed=$true;continue};try{$cur=if(Test-Path -LiteralPath $p){[IO.File]::ReadAllBytes($p)}else{$null};if($null -eq $cur -or (HashBytes $cur) -ne (HashBytes $x)){Backup $p;Install $p $x;$script:changed=$true;Log ('REPAIRED '+$n)}else{Log ('CURRENT '+$n)}}catch{Log ('LOCAL REPAIR ERROR '+$n+': '+$_.Exception.Message);$script:failed=$true}}
foreach($n in @('WinDivert.dll','WinDivert64.sys')){$f=Get-ChildItem -LiteralPath $Root -Filter $n -File -Recurse -ErrorAction SilentlyContinue|Select-Object -First 1;if($f){Log ('NATIVE OK '+$n)}else{Log ('NATIVE MISSING '+$n);$script:failed=$true}}
try{$probe=Join-Path $Root ('.uaud-write-test-'+[Guid]::NewGuid().ToString('N'));[IO.File]::WriteAllText($probe,'ok');if((Get-Content -LiteralPath $probe -Raw) -ne 'ok'){throw 'write/read verification mismatch'};Remove-Item -LiteralPath $probe -Force;Log 'WRITE ACCESS OK'}catch{Log ('WRITE ACCESS FAILED: '+$_.Exception.Message);$script:failed=$true}
$diagnosis='NO REPAIR REQUIRED';if($failed){$diagnosis='REPAIR INCOMPLETE'}elseif($unknown){$diagnosis='VERIFICATION INCOMPLETE'}elseif($changed){$diagnosis='REPAIR SUCCESS'};Log ('[DIAGNOSIS] '+$diagnosis);$sw.Stop();Log ('RUNTIME '+$sw.Elapsed.ToString());if($changed -or $failed -or $unknown){$reportText=@($UARDName+' ver '+$UARDVersion+' - TRUE BASELINE','Run: '+(Get-Date),'Diagnosis: '+$diagnosis,'Middleman: '+$Middleman,'Execution policy / application-control diagnostics captured.','HTTP 409/422 and 4xx/5xx handling is explicit.','Protected boundary unchanged.','',$log);$reportText|Set-Content -LiteralPath $Report -Encoding UTF8;try{Start-Process notepad.exe -ArgumentList @($Report)|Out-Null}catch{}};if($failed){exit 1};if($unknown){exit 2};exit 0
